// Bundles data/*.json into js/data.bundle.js (window.__DATA__) so the demo
// also works when opened from file:// where fetch() of local JSON is blocked.
// Usage: node tools/build-data-bundle.mjs
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join, basename } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const dataDir = join(root, 'data');
const bundle = {};
for (const f of readdirSync(dataDir).filter((f) => f.endsWith('.json')).sort()) {
  bundle[basename(f, '.json')] = JSON.parse(readFileSync(join(dataDir, f), 'utf8'));
}
const out = `/* Generated by tools/build-data-bundle.mjs — do not edit by hand. */\n'use strict';\nwindow.__DATA__ = ${JSON.stringify(bundle)};\n`;
writeFileSync(join(root, 'js', 'data.bundle.js'), out);
console.log('js/data.bundle.js written:', Object.keys(bundle).join(', '), `(${out.length} bytes)`);
